(()=>{'use strict';const reduced=matchMedia('(prefers-reduced-motion:reduce)').matches;let io=null;const motion=document.querySelectorAll('.sc-layer[data-motion]');if(!reduced){if('IntersectionObserver'in window){io=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('sc-visible');io.unobserve(e.target)}}));motion.forEach(n=>{if(n.dataset.trigger==='scroll')io.observe(n);else n.classList.add('sc-visible')})}else motion.forEach(n=>n.classList.add('sc-visible'))}const timers=[];document.querySelectorAll('.sc-slideshow').forEach(el=>{const slides=[...el.querySelectorAll('.sc-slide')];if(!slides.length)return;let i=0,paused=reduced||el.dataset.autoplay!=='true';const paint=()=>slides.forEach((s,j)=>{s.hidden=j!==i});const toggle=el.querySelector('[data-pause]');const sync=()=>{toggle.textContent=paused?'Play':'Pause';toggle.setAttribute('aria-label',paused?'Play slideshow':'Pause slideshow')};const advance=n=>{i=(n+slides.length)%slides.length;paint()};el.querySelector('[data-prev]').addEventListener('click',()=>advance(i-1));el.querySelector('[data-next]').addEventListener('click',()=>advance(i+1));toggle.addEventListener('click',()=>{paused=!paused;sync()});el.addEventListener('focusin',()=>{paused=true;sync()});el.addEventListener('mouseenter',()=>{paused=true;sync()});const ms=Math.max(1800,Number(el.dataset.interval)||4000);timers.push(setInterval(()=>{if(!paused&&!document.hidden)advance(i+1)},ms));sync();paint()});document.addEventListener('click',e=>{const t=e.target.closest('[data-haptic]');if(!t||window.SC_HAPTICS_ENABLED!==true||!navigator.vibrate)return;try{const h=t.dataset.haptic;if(h!=='off')navigator.vibrate(h==='medium'?24:12)}catch{}});addEventListener('pagehide',()=>{timers.forEach(clearInterval);if(io)io.disconnect()},{once:true})})();
